    generate_all,
});

use crate::aap::caps::kb_read;

struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let q = query.query;
        let knowledge = kb_read::lookup(&q.question);
        ConversationContext {
            intent: q.intent,
            question: q.question,
            knowledge,
        }
    }
}

export!(Node);
